CREATE TABLE auth_tenant(id BLOB PRIMARY KEY CHECK(length(id)=16), name TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, row_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE auth_user(id BLOB PRIMARY KEY CHECK(length(id)=16), tenant_id BLOB NOT NULL REFERENCES auth_tenant(id), email TEXT NOT NULL, username TEXT, display_name TEXT, status TEXT NOT NULL, email_verified_at TEXT, last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, row_version INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX auth_user_email_live ON auth_user(tenant_id,email) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX auth_user_username_live ON auth_user(tenant_id,username) WHERE username IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE auth_password(user_id BLOB PRIMARY KEY REFERENCES auth_user(id), password_hash TEXT NOT NULL, algorithm TEXT NOT NULL, parameters TEXT NOT NULL, failed_attempts INTEGER NOT NULL DEFAULT 0, locked_until TEXT, password_changed_at TEXT NOT NULL, row_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE auth_session(id BLOB PRIMARY KEY, user_id BLOB NOT NULL REFERENCES auth_user(id), tenant_id BLOB NOT NULL REFERENCES auth_tenant(id), token_digest BLOB NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, rotated_from_id BLOB REFERENCES auth_session(id), created_at TEXT NOT NULL, last_seen_at TEXT);
CREATE TABLE auth_one_time(id BLOB PRIMARY KEY,user_id BLOB NOT NULL REFERENCES auth_user(id),purpose TEXT NOT NULL,token_digest BLOB NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT,attempt_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(purpose,token_digest));
CREATE TABLE auth_api_key(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),user_id BLOB REFERENCES auth_user(id),service_account_id BLOB,name TEXT NOT NULL,prefix TEXT NOT NULL,secret_digest BLOB NOT NULL UNIQUE,scopes TEXT NOT NULL,expires_at TEXT,revoked_at TEXT,last_used_at TEXT,created_at TEXT NOT NULL,CHECK((user_id IS NULL) != (service_account_id IS NULL)));
CREATE TABLE auth_service_account(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),name TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE auth_passkey(id BLOB PRIMARY KEY,user_id BLOB NOT NULL REFERENCES auth_user(id),credential_id BLOB NOT NULL UNIQUE,public_key BLOB NOT NULL,sign_count INTEGER NOT NULL,transports TEXT NOT NULL,aaguid BLOB,backed_up INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE auth_webauthn_challenge(id BLOB PRIMARY KEY,user_id BLOB REFERENCES auth_user(id),kind TEXT NOT NULL,challenge BLOB NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT,expected_password_hash TEXT,ceremony TEXT);
CREATE TABLE auth_mfa(user_id BLOB PRIMARY KEY REFERENCES auth_user(id),totp_secret_crypt BLOB NOT NULL,key_id TEXT NOT NULL,enabled_at TEXT NOT NULL);
CREATE TABLE auth_recovery_code(id BLOB PRIMARY KEY,user_id BLOB NOT NULL REFERENCES auth_user(id),code_digest BLOB NOT NULL,consumed_at TEXT);
CREATE TABLE auth_permission(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),name TEXT NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE auth_role(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),name TEXT NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE auth_role_permission(role_id BLOB NOT NULL REFERENCES auth_role(id),permission_id BLOB NOT NULL REFERENCES auth_permission(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE auth_membership(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),user_id BLOB NOT NULL REFERENCES auth_user(id),status TEXT NOT NULL);
CREATE TABLE auth_membership_role(membership_id BLOB NOT NULL REFERENCES auth_membership(id),role_id BLOB NOT NULL REFERENCES auth_role(id),PRIMARY KEY(membership_id,role_id));
CREATE TABLE auth_invitation(id BLOB PRIMARY KEY,tenant_id BLOB NOT NULL REFERENCES auth_tenant(id),email TEXT NOT NULL,token_digest BLOB NOT NULL UNIQUE,expires_at TEXT NOT NULL,accepted_at TEXT);
CREATE TABLE auth_invitation_role(invitation_id BLOB NOT NULL REFERENCES auth_invitation(id),role_id BLOB NOT NULL REFERENCES auth_role(id),PRIMARY KEY(invitation_id,role_id));
CREATE TABLE auth_audit(id BLOB PRIMARY KEY,tenant_id BLOB,actor_id BLOB,action TEXT NOT NULL,subject_kind TEXT,subject_id BLOB,outcome TEXT NOT NULL,ip TEXT,user_agent TEXT,created_at TEXT NOT NULL);
CREATE TRIGGER auth_audit_no_update BEFORE UPDATE ON auth_audit BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER auth_audit_no_delete BEFORE DELETE ON auth_audit BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TABLE auth_group(id BLOB PRIMARY KEY CHECK(length(id)=16), tenant_id BLOB NOT NULL REFERENCES auth_tenant(id), name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,name));
CREATE TABLE auth_group_member(group_id BLOB NOT NULL REFERENCES auth_group(id), membership_id BLOB NOT NULL REFERENCES auth_membership(id), PRIMARY KEY(group_id,membership_id));
CREATE TABLE auth_social_state(id BLOB PRIMARY KEY CHECK(length(id)=16), tenant_id BLOB NOT NULL REFERENCES auth_tenant(id), provider TEXT NOT NULL, token_digest BLOB NOT NULL UNIQUE, expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE auth_social_identity(provider TEXT NOT NULL, subject TEXT NOT NULL, user_id BLOB NOT NULL REFERENCES auth_user(id), created_at TEXT NOT NULL, PRIMARY KEY(provider,subject));
CREATE INDEX auth_social_identity_user ON auth_social_identity(user_id);
